package net.officefloor.hq.app.claim;


/**
 * The late charge on a claim: an OPEN (or PENDING) claim whose due-by (fixed when it was created) is before
 * the sheet's today gains the sheet's late percent of its figure for every full 30 days it is
 * overdue, rounded like due; a deferred claim is not overdue. A correction has no late charge. The charge is never bound by a statement; settling freezes it in.
 */
public final class LateCharge {

    public static final int PERIOD_DAYS = 30;

    private LateCharge() {
    }

    /** The charge on a claim's figure; zero when it is not overdue or has no figure. */
    public static BigDecimal of(Claim claim, BigDecimal figure, BigDecimal pct, LocalDate today,
            RoundingMode rounding) {
        if (!claim.getStatus().isOpen() || claim.isDeferredOn(today)) {
            return BigDecimal.ZERO.setScale(2);
        }
        return asOpen(claim, figure, pct, today, rounding);
    }

    /** The charge the claim's figure would carry were it open, whatever its status; re-settling uses it. */
    public static BigDecimal asOpen(Claim claim, BigDecimal figure, BigDecimal pct, LocalDate today,
            RoundingMode rounding) {
        if (figure == null || pct == null || pct.signum() == 0 || claim.isCorrection()) {
            return BigDecimal.ZERO.setScale(2);
        }
        long overdue = ChronoUnit.DAYS.between(claim.getDueBy(), today);
        long periods = overdue > 0 ? overdue / PERIOD_DAYS : 0;
        return Rates.due(figure.multiply(BigDecimal.valueOf(periods)), pct, rounding);
    }

    /** The figure with its late charge added on top; null stays null. */
    public static BigDecimal withCharge(Claim claim, BigDecimal figure, BigDecimal pct, LocalDate today,
            RoundingMode rounding) {
        return figure == null ? null : figure.add(of(claim, figure, pct, today, rounding));
    }
}
=== claim/ClaimStatus.java
package net.officefloor.hq.app.claim;

/**
 * A claim's status. It starts DRAFT; DRAFT -> OPEN -> SETTLED, and DRAFT or OPEN -> VOID. A clerk
 * settling above the clerk limit sends an OPEN claim to PENDING instead: a steward approves it
 * (-> SETTLED) or rejects it (-> OPEN); a PENDING claim may also be voided.
 */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID;

    /** Whether a claim in this status may move to the target status. */
    public boolean canBecome(ClaimStatus target) {
        return switch (target) {
            case OPEN -> this == DRAFT;
            case SETTLED, PENDING -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
            case DRAFT -> false;
        };
    }

    /** Only OPEN, PENDING and SETTLED claims count toward claimed and every total. */
    public boolean counts() {
        return this == OPEN || this == PENDING || this == SETTLED;
    }

    /** OPEN and PENDING claims are open: their due is live, they go overdue and a hold covering their date takes them out of the totals (unless bound). */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }
}
=== claim/ApplyClaimStatus.java
package net.officefloor.hq.app.claim;


public class ApplyClaimStatus {
    public void apply(@Val ValidClaimStatus request, @Val Claim claim, Sheets sheets, People people,
            Rates rates, Periods periods, Settings settings, ClaimNumbering numbering, Out<ClaimNumber> number)
            throws ClaimStatusRefusedException {
        number.set(change(request, claim, sheets, people, rates, periods, settings, numbering));
    }

    /** Applies a status change to the claim by the rules of a single change, returning its number;
     *  throws, leaving the claim as it is, when the change is refused. Bulk settle uses it too. */
    static ClaimNumber change(ValidClaimStatus request, Claim claim, Sheets sheets, People people,
            Rates rates, Periods periods, Settings settings, ClaimNumbering numbering)
            throws ClaimStatusRefusedException {
        RoundingMode rounding = Rounding.of(claim, settings.policyDate(claim.getSheetId()));
        if (periods.isClosed(claim.getSheetId(), claim.getDate())) {
            throw new ClaimStatusRefusedException("No claim dated inside a closed period can change status");
        }
        boolean steward = Settings.STEWARD.equals(settings.role(claim.getSheetId(), request.user()));
        if (request.decision() != ValidClaimStatus.Decision.NONE) {
            // Only a steward approves or rejects, and only a PENDING claim.
            if (claim.getStatus() != ClaimStatus.PENDING) {
                throw new ClaimStatusRefusedException(claim.getStatus(), request.target());
            }
            if (!steward) {
                throw new ClaimStatusRefusedException("Only a steward can approve or reject a PENDING claim");
            }
        } else if (!claim.getStatus().canBecome(request.target())) {
            throw new ClaimStatusRefusedException(claim.getStatus(), request.target());
        }
        if (request.target() == ClaimStatus.SETTLED && claim.getOpenedBy() != null
                && claim.getOpenedBy().equals(request.user())) {
            // Four eyes: the user who opened a claim cannot settle (or approve) it.
            throw new ClaimStatusRefusedException("The user who opened a claim cannot settle it");
        }
        if (request.target() == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(claim.getSheetId()))) {
            throw new ClaimStatusRefusedException("A deferred claim cannot be settled until its deferred-until date");
        }
        ClaimStatus target = request.target();
        if (target == ClaimStatus.SETTLED && request.decision() == ValidClaimStatus.Decision.NONE && !steward) {
            // A clerk settles only within the sheet's clerk limit, judged on the claim's due as shown;
            // a due of n/a is within any limit.
            BigDecimal limit = settings.clerkLimit(claim.getSheetId());
            String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
            BigDecimal fixed = ClaimResponse.fixedDue(claim);
            BigDecimal figure = fixed != null || claim.isBound() ? fixed
                    : Rates.due(claim.getAmount(), rates.find(claim.getSheetId(), grade, claim.getDate()),
                    settings.floor(claim.getSheetId(), claim.getDate()), rounding);
            BigDecimal due = LateCharge.withCharge(claim, figure, settings.latePct(claim.getSheetId(), claim.getDate()),
                    sheets.today(claim.getSheetId()), rounding);
            if (limit != null && due != null && due.compareTo(limit) > 0) {
                // Above the clerk limit the claim awaits a steward's approval.
                target = ClaimStatus.PENDING;
            }
        }
        if (target == ClaimStatus.OPEN && request.decision() == ValidClaimStatus.Decision.NONE) {
            claim.setNumber(numbering.next(claim.getSheetId(), claim.getDate()));
            claim.setOpenedBy(request.user());
        }
        // A voided claim keeps its number; numbers are never reused.
        ClaimNumber number = new ClaimNumber(claim.getNumber());
        if (target == ClaimStatus.SETTLED) {
            // Settling (or approving) fixes the due: the figure a statement bound it to (never while PENDING), else its amount (raised to the floor)
            // at the rate in force on the claim's date, with its late charge as of today frozen in; with no
            // figure it stays live (n/a until a rate is set).
            String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
            BigDecimal figure = claim.isBound() && claim.getStatedDue() != null ? claim.getStatedDue()
                    : Rates.due(claim.getAmount(), rates.find(claim.getSheetId(), grade, claim.getDate()),
                    settings.floor(claim.getSheetId(), claim.getDate()), rounding);
            claim.setSettledDue(LateCharge.withCharge(claim, figure, settings.latePct(claim.getSheetId(), claim.getDate()),
                    sheets.today(claim.getSheetId()), rounding));
        }
        // A rejected claim is OPEN again, so bound again by the last statement if it included it.
        claim.setStatus(target);
        return number;
    }
}
