232	/**
233	 * The late charge on a claim: an OPEN (or PENDING) claim whose due-by (fixed when it was created) is before
234	 * the sheet's today gains the sheet's late percent of its figure for every full 30 days it is
235	 * overdue, rounded like due; a deferred claim is not overdue. A correction has no late charge. The charge is never bound by a statement; settling freezes it in.
236	 */
237	public final class LateCharge {
238	
239	    public static final int PERIOD_DAYS = 30;
240	
241	    private LateCharge() {
242	    }
243	
244	    /** The charge on a claim's figure; zero when it is not overdue or has no figure. */
245	    public static BigDecimal of(Claim claim, BigDecimal figure, BigDecimal pct, LocalDate today,
246	            RoundingMode rounding) {
247	        if (!claim.getStatus().isOpen() || claim.isDeferredOn(today)) {
248	            return BigDecimal.ZERO.setScale(2);
249	        }
250	        return asOpen(claim, figure, pct, today, rounding);
251	    }
252	
253	    /** The charge the claim's figure would carry were it open, whatever its status; re-settling uses it. */
254	    public static BigDecimal asOpen(Claim claim, BigDecimal figure, BigDecimal pct, LocalDate today,
255	            RoundingMode rounding) {
256	        if (figure == null || pct == null || pct.signum() == 0 || claim.isCorrection()) {
257	            return BigDecimal.ZERO.setScale(2);
258	        }
259	        long overdue = ChronoUnit.DAYS.between(claim.getDueBy(), today);
260	        long periods = overdue > 0 ? overdue / PERIOD_DAYS : 0;
261	        return Rates.due(figure.multiply(BigDecimal.valueOf(periods)), pct, rounding);
262	    }
263	
264	    /** The figure with its late charge added on top; null stays null. */
265	    public static BigDecimal withCharge(Claim claim, BigDecimal figure, BigDecimal pct, LocalDate today,
266	            RoundingMode rounding) {
267	        return figure == null ? null : figure.add(of(claim, figure, pct, today, rounding));
268	    }
