273	/**
274	 * A claim's status. It starts DRAFT; DRAFT -> OPEN -> SETTLED, and DRAFT or OPEN -> VOID. A clerk
275	 * settling above the clerk limit sends an OPEN claim to PENDING instead: a steward approves it
276	 * (-> SETTLED) or rejects it (-> OPEN); a PENDING claim may also be voided.
277	 */
278	public enum ClaimStatus {
279	    DRAFT, OPEN, PENDING, SETTLED, VOID;
280	
281	    /** Whether a claim in this status may move to the target status. */
282	    public boolean canBecome(ClaimStatus target) {
283	        return switch (target) {
284	            case OPEN -> this == DRAFT;
285	            case SETTLED, PENDING -> this == OPEN;
286	            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
287	            case DRAFT -> false;
288	        };
289	    }
290	
291	    /** Only OPEN, PENDING and SETTLED claims count toward claimed and every total. */
292	    public boolean counts() {
293	        return this == OPEN || this == PENDING || this == SETTLED;
294	    }
295	
296	    /** OPEN and PENDING claims are open: their due is live, they go overdue and a hold covering their date takes them out of the totals (unless bound). */
297	    public boolean isOpen() {
298	        return this == OPEN || this == PENDING;
299	    }
