305	public class ApplyClaimStatus {
306	    public void apply(@Val ValidClaimStatus request, @Val Claim claim, Sheets sheets, People people,
307	            Rates rates, Periods periods, Settings settings, ClaimNumbering numbering, Out<ClaimNumber> number)
308	            throws ClaimStatusRefusedException {
309	        number.set(change(request, claim, sheets, people, rates, periods, settings, numbering));
310	    }
311	
312	    /** Applies a status change to the claim by the rules of a single change, returning its number;
313	     *  throws, leaving the claim as it is, when the change is refused. Bulk settle uses it too. */
314	    static ClaimNumber change(ValidClaimStatus request, Claim claim, Sheets sheets, People people,
315	            Rates rates, Periods periods, Settings settings, ClaimNumbering numbering)
316	            throws ClaimStatusRefusedException {
317	        RoundingMode rounding = Rounding.of(claim, settings.policyDate(claim.getSheetId()));
318	        if (periods.isClosed(claim.getSheetId(), claim.getDate())) {
319	            throw new ClaimStatusRefusedException("No claim dated inside a closed period can change status");
320	        }
321	        boolean steward = Settings.STEWARD.equals(settings.role(claim.getSheetId(), request.user()));
322	        if (request.decision() != ValidClaimStatus.Decision.NONE) {
323	            // Only a steward approves or rejects, and only a PENDING claim.
324	            if (claim.getStatus() != ClaimStatus.PENDING) {
325	                throw new ClaimStatusRefusedException(claim.getStatus(), request.target());
326	            }
327	            if (!steward) {
328	                throw new ClaimStatusRefusedException("Only a steward can approve or reject a PENDING claim");
329	            }
330	        } else if (!claim.getStatus().canBecome(request.target())) {
331	            throw new ClaimStatusRefusedException(claim.getStatus(), request.target());
332	        }
333	        if (request.target() == ClaimStatus.SETTLED && claim.getOpenedBy() != null
334	                && claim.getOpenedBy().equals(request.user())) {
335	            // Four eyes: the user who opened a claim cannot settle (or approve) it.
336	            throw new ClaimStatusRefusedException("The user who opened a claim cannot settle it");
337	        }
338	        if (request.target() == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(claim.getSheetId()))) {
339	            throw new ClaimStatusRefusedException("A deferred claim cannot be settled until its deferred-until date");
340	        }
341	        ClaimStatus target = request.target();
342	        if (target == ClaimStatus.SETTLED && request.decision() == ValidClaimStatus.Decision.NONE && !steward) {
343	            // A clerk settles only within the sheet's clerk limit, judged on the claim's due as shown;
344	            // a due of n/a is within any limit.
345	            BigDecimal limit = settings.clerkLimit(claim.getSheetId());
346	            String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
347	            BigDecimal fixed = ClaimResponse.fixedDue(claim);
348	            BigDecimal figure = fixed != null || claim.isBound() ? fixed
349	                    : Rates.due(claim.getAmount(), rates.find(claim.getSheetId(), grade, claim.getDate()),
350	                    settings.floor(claim.getSheetId(), claim.getDate()), rounding);
351	            BigDecimal due = LateCharge.withCharge(claim, figure, settings.latePct(claim.getSheetId(), claim.getDate()),
352	                    sheets.today(claim.getSheetId()), rounding);
353	            if (limit != null && due != null && due.compareTo(limit) > 0) {
354	                // Above the clerk limit the claim awaits a steward's approval.
355	                target = ClaimStatus.PENDING;
356	            }
357	        }
358	        if (target == ClaimStatus.OPEN && request.decision() == ValidClaimStatus.Decision.NONE) {
359	            claim.setNumber(numbering.next(claim.getSheetId(), claim.getDate()));
360	            claim.setOpenedBy(request.user());
361	        }
362	        // A voided claim keeps its number; numbers are never reused.
363	        ClaimNumber number = new ClaimNumber(claim.getNumber());
364	        if (target == ClaimStatus.SETTLED) {
365	            // Settling (or approving) fixes the due: the figure a statement bound it to (never while PENDING), else its amount (raised to the floor)
366	            // at the rate in force on the claim's date, with its late charge as of today frozen in; with no
367	            // figure it stays live (n/a until a rate is set).
368	            String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
369	            BigDecimal figure = claim.isBound() && claim.getStatedDue() != null ? claim.getStatedDue()
370	                    : Rates.due(claim.getAmount(), rates.find(claim.getSheetId(), grade, claim.getDate()),
371	                    settings.floor(claim.getSheetId(), claim.getDate()), rounding);
372	            claim.setSettledDue(LateCharge.withCharge(claim, figure, settings.latePct(claim.getSheetId(), claim.getDate()),
373	                    sheets.today(claim.getSheetId()), rounding));
374	        }
375	        // A rejected claim is OPEN again, so bound again by the last statement if it included it.
376	        claim.setStatus(target);
377	        return number;
378	    }
