386	    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?");
387	    private static final Pattern SIGNED_AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");
388	    private static final Pattern NUMBER = Pattern.compile("\\d+|\\S+-\\d+");
389	
390	    public void validate(@RequestBody ClaimRequest request, Out<ValidClaim> body) throws InvalidClaimException {
391	        body.set(check(request));
392	    }
