394	    /** The claim form's rules on its body alone; the sheet's rules are checked when the claim is saved. */
395	    static ValidClaim check(ClaimRequest request) throws InvalidClaimException {
396	        BigDecimal amount = signedAmount(request.amount());
397	        String corrects = corrects(request.corrects());
398	        if (amount.signum() < 0 && corrects == null) {
399	            throw new InvalidClaimException("A negative amount is a correction: it must name the claim it corrects");
400	        }
401	        if (amount.signum() >= 0 && corrects != null) {
402	            throw new InvalidClaimException("Only a correction (a negative amount) can name a claim it corrects");
403	        }
404	        String rawDate = request.date() == null ? "" : request.date().trim();
405	        LocalDate date = null;
406	        if (!rawDate.isEmpty()) {
407	            try {
408	                date = LocalDate.parse(rawDate);
409	            } catch (DateTimeParseException e) {
410	                throw new InvalidClaimException("The date is not a date");
411	            }
412	        }
413	        String note = request.note() == null ? "" : request.note().trim();
414	        return new ValidClaim(amount, date, note, request.user(), corrects);
415	    }
416	
417	    /** The claim form's amount: with at most two decimals; a negative one is a correction. */
418	    static BigDecimal signedAmount(String raw) throws InvalidClaimException {
419	        String amount = raw == null ? "" : raw.trim();
420	        if (!SIGNED_AMOUNT.matcher(amount).matches()) {
421	            throw new InvalidClaimException("The amount must have at most two decimals");
422	        }
423	        return new BigDecimal(amount).setScale(2);
424	    }
425	
426	    /** The number of the claim a correction corrects; null when blank. */
427	    static String corrects(String raw) throws InvalidClaimException {
428	        String corrects = raw == null ? "" : raw.trim();
