            throw new ClaimStatusRefusedException("A " + status + " claim cannot move to another person");
        }
        Person to = null;
        try {
            to = people.find(claim.getSheetId(), Long.parseLong(request.toPersonId()));
        } catch (NumberFormatException e) {
