16	/**
17	 * The sheet's figures as the screen shows them — each person's claimed and due-total, and the
18	 * sheet's claimed-total and due-total, each person's and the sheet's overdue-total (the dues of their overdue claims, uncapped), each person's due-total held to the sheet's cap — worked out on the server so a change can audit what it
19	 * moved: after the change's own lines, one ROLLUP line per person whose figures changed (people in
20	 * the order they were added; a new person counts as changed), then a TOTALS line when the sheet's
21	 * totals changed.
22	 */
23	@Service
24	public class Rollup {
25	
26	    private static final String NA = "n/a";
27	
28	    private final People people;
29	    private final Claims claims;
30	    private final Rates rates;
31	    private final Sheets sheets;
32	    private final Settings settings;
33	    private final Audit audit;
34	
35	    public Rollup(People people, Claims claims, Rates rates, Sheets sheets, Settings settings, Audit audit) {
36	        this.people = people;
37	        this.claims = claims;
38	        this.rates = rates;
39	        this.sheets = sheets;
40	        this.settings = settings;
41	        this.audit = audit;
42	    }
