44	    /** The sheet's figures now. */
45	    public RollupFigures figures(String sheetId) {
46	        LocalDate today = sheets.today(sheetId);
47	        LocalDate policyDate = settings.policyDate(sheetId);
48	        BigDecimal cap = settings.cap(sheetId);
49	        List<Claim> all = claims.list(sheetId);
50	        Map<Long, RollupFigures.PersonFigures> byPerson = new LinkedHashMap<>();
51	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
52	        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
53	        BigDecimal overdueTotal = BigDecimal.ZERO.setScale(2);
54	        for (Person person : people.list(sheetId)) {
55	            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
56	            BigDecimal due = BigDecimal.ZERO.setScale(2);
57	            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
58	            boolean anyFigure = false;
59	            for (Claim claim : all) {
60	                if (claim.getPersonId() != person.getId() || !person.countsLive(claim, today)) {
61	                    continue;
62	                }
63	                claimed = claimed.add(claim.getAmount());
64	                BigDecimal figure = due(claim, person, today, policyDate);
65	                if (figure != null) {
66	                    anyFigure = true;
67	                    due = due.add(figure);
68	                    if (isOverdue(claim, today)) {
69	                        overdue = overdue.add(figure);
70	                    }
71	                }
72	            }
73	            // n/a only when no claim keeps or gets a figure (each at the grade in force on its date).
74	            boolean na = !anyFigure && rates.find(sheetId, person.getGrade(), today) == null;
75	            due = Settings.capped(due, cap);
76	            claimedTotal = claimedTotal.add(claimed);
77	            if (!na) {
78	                dueTotal = dueTotal.add(due);
79	            }
80	            overdueTotal = overdueTotal.add(overdue);
81	            byPerson.put(person.getId(), new RollupFigures.PersonFigures(person.getName(),
82	                    show(claimed), na ? NA : show(due), show(overdue)));
83	        }
84	        return new RollupFigures(byPerson, show(claimedTotal), show(dueTotal), show(overdueTotal));
85	    }
