87	    /** A claim's due as the screen shows it now; null for n/a. */
88	    public BigDecimal due(Claim claim, Person person) {
89	        String sheetId = claim.getSheetId();
90	        return due(claim, person, sheets.today(sheetId), settings.policyDate(sheetId));
91	    }
92	
93	    /** A claim's due: fixed when settled or bound by a statement, else its amount (raised to the floor in force on its date) at the rate
94	     *  of its person's grade in force on its date; with its late charge (at the late percent in force on its date) as of today on top. */
95	    private BigDecimal due(Claim claim, Person person, LocalDate today, LocalDate policyDate) {
96	        String sheetId = claim.getSheetId();
97	        RoundingMode rounding = Rounding.of(claim, policyDate);
98	        BigDecimal fixed = ClaimResponse.fixedDue(claim);
99	        BigDecimal figure = fixed != null || claim.isBound() ? fixed
100	                : Rates.due(claim.getAmount(), rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate()),
101	                        settings.floor(sheetId, claim.getDate()), rounding);
102	        return LateCharge.withCharge(claim, figure, settings.latePct(sheetId, claim.getDate()), today, rounding);
103	    }
