105	    /** Audit (on commit) the figures that moved since {@code before}, as taken by {@code user}. */
106	    public void recordChanges(String sheetId, String user, RollupFigures before) {
107	        RollupFigures after = figures(sheetId);
108	        String prefix = " sheet=" + sheetId + " by=" + user;
109	        after.people().forEach((id, now) -> {
110	            RollupFigures.PersonFigures was = before.people().get(id);
111	            if (was == null || !Objects.equals(was.claimed(), now.claimed())
112	                    || !Objects.equals(was.dueTotal(), now.dueTotal())
113	                    || !Objects.equals(was.overdueTotal(), now.overdueTotal())) {
114	                audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name()
115	                        + " claimed=" + now.claimed() + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
116	            }
117	        });
118	        if (!before.claimedTotal().equals(after.claimedTotal()) || !before.dueTotal().equals(after.dueTotal())
119	                || !before.overdueTotal().equals(after.overdueTotal())) {
120	            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + after.claimedTotal()
121	                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
122	        }
123	    }
