125	    /** A claim is overdue when it is OPEN (or PENDING) and its due-by is before the sheet's today. */
126	    private static boolean isOverdue(Claim claim, LocalDate today) {
127	        return claim.getStatus().isOpen() && claim.getDueBy() != null && claim.getDueBy().isBefore(today);
128	    }
