251	            @RequestBody ClosePeriodRequest request, Periods periods, People people, Claims claims, Rates rates,
252	            Settings settings, Sheets sheets, Audit audit, ObjectResponse<List<PeriodResponse>> response) throws InvalidPeriodException {
253	        PeriodResponse period = periods.lock(sheetId, name);
254	        if (period == null) {
255	            throw new InvalidPeriodException("No period named " + name + " is on the sheet");
256	        }
257	        if (period.closed()) {
258	            throw new InvalidPeriodException("The period " + name + " is already closed");
259	        }
260	        LocalDate from = LocalDate.parse(period.from());
261	        LocalDate to = LocalDate.parse(period.to());
262	        BigDecimal total = BigDecimal.ZERO.setScale(2);
263	        LocalDate policyDate = settings.policyDate(sheetId);
264	        LocalDate today = sheets.today(sheetId);
265	        List<Claim> all = claims.list(sheetId);
266	        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
267	        for (Person person : people.list(sheetId)) {
268	            BigDecimal personTotal = BigDecimal.ZERO.setScale(2);
269	            for (Claim claim : all) {
270	                if (claim.getPersonId() != person.getId() || !person.countsLive(claim, today)
271	                        || claim.getDate().isBefore(from) || claim.getDate().isAfter(to)) {
272	                    continue;
273	                }
274	                RoundingMode rounding = Rounding.of(claim, policyDate);
275	                BigDecimal fixed = ClaimResponse.fixedDue(claim);
276	                BigDecimal figure = fixed != null || claim.isBound() ? fixed
277	                        : Rates.due(claim.getAmount(), rates.find(sheetId, person.gradeOn(claim.getDate()), claim.getDate()),
278	                        settings.floor(sheetId, claim.getDate()), rounding);
279	                if (figure != null) {
280	                    personTotal = personTotal.add(LateCharge.withCharge(claim, figure, settings.latePct(sheetId, claim.getDate()), today, rounding));
281	                }
282	            }
283	            personTotals.put(person.getId(), personTotal);
284	            total = total.add(personTotal);
285	        }
286	        periods.close(sheetId, name, total, personTotals);
287	        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + request.user()
288	                + " period=" + name + " total=" + total.toPlainString());
289	        response.send(periods.list(sheetId));
290	    }
291	}
