769	/**
770	 * Takes a statement: the person's due-total as the screen shows it now (the sum of their counting
771	 * claims' figures — fixed or at the rate in force on each claim's date, raised to the floor in force on its date; n/a when their grade has no
772	 * rate today and no claim keeps a figure; an overdue claim's late charge included; held to the sheet's cap), and binds each
773	 * counting claim to its figure now — never its late charge, which keeps following the sheet's today.
774	 * A claim that does not count (an unbound OPEN claim dated within one of its person's holds, or a deferred claim, included) is left unbound.
775	 */
776	public class TakeStatement {
777	    public void take(@Val Person person, Claims claims, Rates rates, Sheets sheets, People people,
778	            Settings settings, Out<Statement> statement) {
779	        String sheetId = person.getSheetId();
780	        LocalDate today = sheets.today(sheetId);
781	        LocalDate policyDate = settings.policyDate(sheetId);
782	        List<Claim> own = claims.ofPerson(sheetId, person.getId());
783	        BigDecimal total = BigDecimal.ZERO.setScale(2);
784	        boolean anyFigure = false;
785	        int counted = 0;
786	        for (Claim claim : own) {
787	            if (!person.countsLive(claim, today)) {
788	                claim.setStated(false);
789	                claim.setStatedDue(null);
790	            } else {
791	                RoundingMode rounding = Rounding.of(claim, policyDate);
792	                BigDecimal fixed = ClaimResponse.fixedDue(claim);
793	                // A bound claim keeps its figure (even n/a); a live one is worked at the rate on its date.
794	                BigDecimal figure = fixed != null || claim.isBound() ? fixed
795	                        : Rates.due(claim.getAmount(), rates.find(sheetId, person.gradeOn(claim.getDate()), claim.getDate()),
796	                        settings.floor(sheetId, claim.getDate()), rounding);
797	                anyFigure |= fixed != null;
798	                if (figure != null) {
799	                    anyFigure = true;
800	                    total = total.add(LateCharge.withCharge(claim, figure, settings.latePct(sheetId, claim.getDate()), today, rounding));
801	                }
802	                claim.setStated(true);
803	                claim.setStatedDue(figure);
804	                counted++;
805	            }
806	            claims.bind(claim);
807	        }
808	        // n/a only when no claim keeps or gets a figure (each at the grade in force on its date).
809	        boolean na = !anyFigure && rates.find(sheetId, person.getGrade(), today) == null;
810	        BigDecimal dueTotal = na ? null : Settings.capped(total, settings.cap(sheetId));
811	        person.setStatementCount(person.getStatementCount() + 1);
812	        person.setStatedTotal(dueTotal);
813	        person.setStatementDate(today);
814	        people.saveStatement(person);
815	        statement.set(new Statement(dueTotal, counted));
816	    }
