export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** A claim; `amount` is shown with two decimals ("10.25"); `number` is the one given when it was
 *  opened (a voided claim keeps it), "" for a draft; `due` is the due fixed when it was settled, else the
 *  figure the person's last statement bound it to, "" while its due is live (worked from the current
 *  rate) or bound to n/a (a PENDING claim is never bound: its due is live); `stated` is whether the last statement bound it. A claim with a negative
 *  amount is a correction: its due has no floor and no late charge. */
export type Claim = {
  id: string;
  personId: string;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string;
  due: string;
  /** The user who opened the claim, "" if it was never opened. */
  openedBy: string;
  stated: boolean;
  /** The number of the SETTLED claim a correction (a negative amount) corrects, "" for any other claim. */
  corrects: string;
  /** The date the claim's rounding goes by: a correction's is the date of the claim it corrects. */
  roundingDate: string;
  /** The claim's due-by, fixed when it was created: its date plus the terms of its person's grade in force on that date. */
  dueBy: string;
  /** The claim's status log, oldest first: "<STATUS> by <user> on <date> due=<due>" per status it has had. */
  log: string[];
  /** The date the claim was last deferred until, "" if it was never deferred. */
  deferredUntil: string;
};

/** OPEN and PENDING claims are open: their due is live (unless bound), they go overdue and a hold
 *  takes them out of the totals. */
export const isOpen = (c: { status?: string }) => c.status === 'OPEN' || c.status === 'PENDING';

/** Only OPEN, PENDING and SETTLED claims count toward claimed, due-total and every total. */
export const counts = (c: Claim) => isOpen(c) || c.status === 'SETTLED';

/** Whether a statement binds the claim's figure now: a PENDING claim is never bound. */
export const isBound = (c: Claim) => c.stated && c.status !== 'PENDING';

/** Whether a claim is deferred on the sheet's today: OPEN and deferred until a later date. A deferred claim
 *  counts in no total, is not overdue, cannot be settled and is left unbound by a statement. */
export const isDeferred = (c: { status?: string; deferredUntil?: string }, today: string | undefined) =>
  c.status === 'OPEN' && !!c.deferredUntil && today !== undefined && today < c.deferredUntil;

/** Whether a claim counts in the live totals: it counts, is not deferred on the sheet's today, and is not
 *  open, unbound and dated within one of its person's holds (`heldOn`). */
export const countsLive = (c: Claim, heldOn: (date: string) => boolean, today: string | undefined) =>
  counts(c) && !isDeferred(c, today) && !(isOpen(c) && !isBound(c) && heldOn(c.date));

export const claimsKey = (sheet: string) => ['sheet', sheet, 'claims'] as const;

/** The sheet's claims, newest first. */
export function useClaims(sheet: string): Claim[] {
  const { data } = useQuery({
    queryKey: claimsKey(sheet),
    queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheet)}/claims`),
    enabled: sheet !== '',
  });
  return data ?? [];
}

/** The amounts of the claims that count added up, shown with two decimals. Summed in whole cents
 *  so no float drift shows. */
export function sumAmounts(claims: Claim[]): string {
  const cents = claims.filter(counts).reduce((sum, c) => sum + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}

/** `version` goes up on every save; an editor sends back the version it loaded, so a save over
 *  someone else's newer one is refused. `statementCount` is how many statements were taken;
 *  `statedTotal` is the last one's due-total ("n/a" possible, "" when none) and `statementDate` the
 *  sheet's today when it was taken ("" when none). `retired` is whether a retirement date is set
 *  (retired at once, whatever the date) and `retiredFrom` is that date ("" when none). `held` is
 *  whether the person has any hold and `holds` lists each (from, to; to "" when open-ended): their
 *  OPEN claims dated within one, unless bound by a statement, count in no live total. `patrons` are the
 *  names of the people they named as patrons, sorted, and `patronIds` those people's ids. `grade`
 *  is the grade in force on the sheet's today when loaded and `grades` every grade recorded. */
export type Person = {
  id: string;
  name: string;
  grade: string;
  version: number;
  statementCount: number;
  statedTotal: string;
  statementDate: string;
  retired: boolean;
  retiredFrom: string;
  held: boolean;
  holds: HoldFrom[];
  patrons: string[];
  patronIds: string[];
  grades: GradeFrom[];
};

/** A hold from a date to a date, both included (YYYY-MM-DD; to "" when open-ended). */
export type HoldFrom = { from: string; to: string };

/** Whether one of the person's holds covers the date. */
export const heldOn = (person: Person, date: string) =>
  person.holds.some((h) => h.from <= date && (h.to === '' || date <= h.to));

/** A grade in force from a date (YYYY-MM-DD; "" for the beginning of time). */
export type GradeFrom = { from: string; grade: string };

/** The person's grade in force on a date: the one with the latest from-date on or before it (with
 *  no date yet, the one in force on the sheet's today as loaded). */
export function gradeOn(person: Person, date: string | undefined): string {
  if (date === undefined) return person.grade;
  let found: GradeFrom | undefined;
  for (const g of person.grades) {
    if (g.from <= date && (found === undefined || g.from >= found.from)) found = g;
  }
  return found?.grade ?? person.grade;
}

export const GRADES = ['A', 'B', 'C'] as const;

export const peopleKey = (sheet: string) => ['sheet', sheet, 'people'] as const;

/** The sheet's people, in the order they were added. */
export function usePeople(sheet: string): Person[] {
  const { data } = useQuery({
    queryKey: peopleKey(sheet),
    queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheet)}/people`),
    enabled: sheet !== '',
  });
  return data ?? [];
}

/** A grade's rate: a percent shown with two decimals ("12.50"), in force from a date (YYYY-MM-DD;
 *  "" for from the beginning of time) through a date ("" for no end). */
export type Rate = { grade: string; rate: string; from: string; to: string };

export const ratesKey = (sheet: string) => ['sheet', sheet, 'rates'] as const;

/** The sheet's rates, by grade then from-date (from the beginning of time first). */
export function useRates(sheet: string): Rate[] {
  const { data } = useQuery({
    queryKey: ratesKey(sheet),
    queryFn: () => getJson<Rate[]>(`/api/sheets/${encodeURIComponent(sheet)}/rates`),
    enabled: sheet !== '',
  });
  return data ?? [];
}

/** The grade's rate in force on a date: the one with the latest from-date on or before it;
 *  undefined when none applies, when that one's to-date is before the date (or the date is not known yet). */
export function rateOn(rates: Rate[], grade: string, date: string | undefined): string | undefined {
  if (date === undefined) return undefined;
  let found: Rate | undefined;
  for (const r of rates) {
    if (r.grade === grade && r.from <= date && (found === undefined || r.from >= found.from)) found = r;
  }
  if (found === undefined || (found.to !== '' && found.to < date)) return undefined;
  return found.rate;
}

/** A role a user name holds on the sheet: clerk (any name not listed) or steward. */
export type Role = { user: string; role: string };

/** The sheet's settings, each dated one as in force on the sheet's today: the clerk limit with two decimals ("" for no limit), the floor with two
 *  decimals (a claim's live due is at least it), the terms in days (a new claim's due-by is its date
 *  plus them, unless its person's grade has its own terms), the late percent with two decimals (an overdue claim gains it of its figure for every
 *  full 30 days overdue), the policy date ("" for blank: the sheet's today), the period numbering from ("" for off: from it,
 *  a claim opened is numbered within its period), the roles set and each grade's own terms in days, by grade
 *  (a grade not listed uses the sheet's terms), and the cap with two decimals ("" for none: a person's due-total is at most it). */
export type Settings = { clerkLimit: string; floor: string; terms: string; latePct: string; policyDate: string; periodNumberingFrom: string; roles: Role[]; gradeTerms: Record<string, string>; cap: string; dated: Record<string, Dated[]> };

/** A value recorded for a dated setting (clerk-limit, floor, terms, terms-<grade>, late-pct, cap): the date
 *  it is in force from and the value ("" for none). The figures shown in Settings are those in force on the
 *  sheet's today; these are every value recorded, oldest first. */
export type Dated = { from: string; value: string };

/** The value of a dated setting in force on a date: the one with the latest from-date on or before it,
 *  else the sheet's starting value. */
export function inForce(settings: Settings | undefined, key: string, date: string, start: string): string {
  const before = (settings?.dated?.[key] ?? []).filter((d) => d.from <= date);
  const found = before[before.length - 1];
  return found === undefined || found.value === '' ? start : found.value;
}

/** The floor a sheet starts with, used until its settings have loaded. */
export const DEFAULT_FLOOR = '1.00';

export const settingsKey = (sheet: string) => ['sheet', sheet, 'settings'] as const;

export function useSettings(sheet: string): Settings | undefined {
  const { data } = useQuery({
    queryKey: settingsKey(sheet),
    queryFn: () => getJson<Settings>(`/api/sheets/${encodeURIComponent(sheet)}/settings`),
    enabled: sheet !== '',
  });
  return data;
}

/** The sheet's floor in force on a date (a claim's: its date). */
export function useFloor(sheet: string): (date: string) => string {
  const settings = useSettings(sheet);
  return (date) => inForce(settings, 'floor', date, DEFAULT_FLOOR);
}

/** The late percent a sheet starts with, used until its settings have loaded. */
export const DEFAULT_LATE_PCT = '0.00';

/** The sheet's late percent in force on a date (a claim's: its date). */
export function useLatePct(sheet: string): (date: string) => string {
  const settings = useSettings(sheet);
  return (date) => inForce(settings, 'late-pct', date, DEFAULT_LATE_PCT);
}

/** The sheet's policy date: the one set, or the sheet's today when it is blank. A claim dated before
 *  it rounds half up, one on or after it half to even. Undefined while loading. */
export function usePolicyDate(sheet: string): string | undefined {
  const set = useSettings(sheet)?.policyDate;
  const today = useSheetToday(sheet);
  return set ? set : today;
}

/** The sheet's cap in force on its today ("" for none): a person's due-total is at most it. */
export function useCap(sheet: string): string {
  return useSettings(sheet)?.cap ?? '';
}

/** A period: a name unique on the sheet, from and to dates (YYYY-MM-DD, both inclusive), whether it
 *  is closed, the due-total fixed when it was closed ("" while open), and each person's due-total for
 *  it fixed then, by person id (empty while open; a person added later has none). */
export type Period = {
  name: string;
  from: string;
  to: string;
  closed: boolean;
  closedTotal: string;
  closedPersonTotals: Record<string, string>;
};

export const periodsKey = (sheet: string) => ['sheet', sheet, 'periods'] as const;

/** The sheet's periods, by from-date. */
export function usePeriods(sheet: string): Period[] {
  const { data } = useQuery({
    queryKey: periodsKey(sheet),
    queryFn: () => getJson<Period[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods`),
    enabled: sheet !== '',
  });
  return data ?? [];
}

/** The period whose dates contain a date; periods never overlap, so there is at most one. */
export function periodOf(periods: Period[], date: string): Period | undefined {
  return periods.find((p) => p.from <= date && date <= p.to);
}
